# Replace section 1.1 of the v19 report and add the new references to the bibliography.
# usage: python3 -I v20_intro.py <unpacked_dir>
import re, sys
from xml.sax.saxutils import escape

D = sys.argv[1]
P = f"{D}/word/document.xml"
x = open(P, encoding="utf8").read()

def run(t, hl=False):
    rpr = "<w:rPr>" + ('<w:highlight w:val="yellow"/>' if hl else "") + "<w:cs/></w:rPr>"
    return f'<w:r>{rpr}<w:t xml:space="preserve">{escape(t)}</w:t></w:r>'

def para(text):
    # [[...]] marks text to highlight (data the author still has to fill in from HDC)
    parts = re.split(r"(\[\[.*?\]\])", text)
    runs = "".join(run(p[2:-2], True) if p.startswith("[[") else run(p) for p in parts if p)
    return f'<w:p><w:pPr><w:ind w:firstLine="720"/><w:jc w:val="thaiDistribute"/></w:pPr>{runs}</w:p>'

def ref(text):
    parts = re.split(r"(\[\[.*?\]\])", text)
    runs = "".join(run(p[2:-2], True) if p.startswith("[[") else run(p) for p in parts if p)
    return f'<w:p><w:pPr><w:ind w:left="720" w:hanging="720"/></w:pPr>{runs}</w:p>'

